// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Ensure the caller is not the owner to avoid onlyOwner revert
        vm.assume(_owner != c.owner());
        vm.prank(c.owner());
        c.setOwner(_owner);
        assertTrue(c.owner() == _owner);
    }
}

